"""Resolve newly source-located studies, preserving metadata receipts."""
import json
import subprocess
from pathlib import Path
q=Path(__file__).resolve().parents[1]

def cli(name,args):
    r=subprocess.run(['./bin/bio',*args],capture_output=True,text=True)
    (q/'outputs'/f'{name}.json').write_text(r.stdout)
    if r.returncode:
        print('FAILED',name,r.stdout,r.stderr)
        return None
    return json.loads(r.stdout)
for term in ['Nedd4','H2B','monoubiquitination']:
    d=cli('forum/search-'+term,['community','search','--text',term,'--limit','15'])
    print('FORUM',term,d)
for label in ['rnf40','figlia']:
    d=json.loads((q/f'outputs/{label}-discovery.json').read_text())
    for hit in d['resources']:
        s=cli(label+'-source',['data','show',hit])
        r=s['profiles'][0]['facts']['source_record']
        print(label,{k:r.get(k) for k in ['title','pmcid','doi','abstractText']})
        if r.get('pmcid'):
            a=cli(label+'-resolve',['resolve',r['pmcid'],'--provider','europepmc'])
            if a:
                b=cli(label+'-assets',['data','list','--scope',a['bundle'],'--limit','100'])
                print('ASSETS',label, b)
r=json.loads((q/'outputs/nedd4-geo-resolve.json').read_text())
print('NEDD_GEO_RESOLVE',r)
if r.get('bundle'):
    print('NEDD_GEO_ASSETS',cli('nedd4-geo-assets',['data','list','--scope',r['bundle'],'--limit','50']))

{
  "version": 1,
  "stage": "after five RNA contrasts, before Nedd4 or RNF40 expression-value inspection",
  "program": "same fixed myelin7, unchanged coverage and uncertainty rules in analysis-plan.r001.json",
  "Nedd4": {"reason":"new independent E3-ubiquitin experiment, P5 mouse nerve; source reports myelin loss and cycle increase", "test":"Does output loss occur with nondepleted Egr2/Sox10 or with regulator RNA loss?", "prediction":"A generic downstream myelin decline will not by itself reproduce Raptor's Egr2-nondepletion pattern; treat as a cross-perturbation challenge, not direct replication", "success_rule_for_shared_pattern":"both regulator lower95 > -0.5 and myelin7-minus-Egr2 upper95 < -0.5", "prior_exposure":"source aggregate myelin/cycle findings only; no regulator values yet"},
  "RNF40": {"reason":"source-located EGR2-guided H2B monoubiquitination provides a cofactor/chromatin subedge", "prediction":"myelin7-minus-Egr2 upper95 < -0.5, Egr2 and Sox10 lower95 > -0.5", "limits":"would support nondepletion, not necessarily equivalence or direct TF activity; own matched chromatin assays required for mechanistic inference", "prior_exposure":"paper citation title, not expression matrix; dataset ascertainment based on mechanism"},
  "orthogonal_TEAD1": {"purpose":"quantify source-deposited Krox20/MPZ/MBP protein contrast to challenge abundance-only sufficiency; no paired RNA/protein rates", "prior_exposure":"published Krox20 preservation/increase known, Krox20 Prism numbers viewed; explicitly retrospective"}
}
